            DockPanel header = new DockPanel { Background = Brushes.White }; header.MouseLeftButtonDown += (s, e) => { if (e.ButtonState == MouseButtonState.Pressed) DragMove(); }; Button close = new Button { Content = "×", Width = 48, Height = 40, Margin = new Thickness(0, 7, 7, 7), FontSize = 22, Foreground = Text(92, 105, 123), Background = Brushes.Transparent, BorderThickness = new Thickness(0), Cursor = Cursors.Hand }; close.Click += (s, e) => DialogResult = false; DockPanel.SetDock(close, Dock.Right); header.Children.Add(close); header.Children.Add(new TextBlock { Text = "DBC信号配置", FontSize = 18, FontWeight = FontWeights.SemiBold, Foreground = Text(32, 43, 59), VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(22, 0, 12, 0) }); root.Children.Add(header); Border actionHeader = new Border { Background = new SolidColorBrush(Color.FromRgb(248, 250, 253)), BorderBrush = BorderColor(), BorderThickness = new Thickness(0, 1, 0, 1), Padding = new Thickness(18, 10, 18, 10) }; WrapPanel actionFields = new WrapPanel { VerticalAlignment = VerticalAlignment.Center }; actionFields.Children.Add(FieldLabel("动作来源", 0)); actionFields.Children.Add(ReadOnlyField("产品DBC通信", 145)); actionFields.Children.Add(FieldLabel("目标设备/协议", 14)); actionFields.Children.Add(ReadOnlyField(messageName, 180)); actionFields.Children.Add(FieldLabel("功能", 14)); actionFields.Children.Add(ReadOnlyField(mode, 125)); actionFields.Children.Add(FieldLabel("动作名称", 14)); _stepName = new TextBox { Text = string.IsNullOrWhiteSpace(stepName) ? "新动作（未配置）" : stepName, Width = 270, Height = 34, Padding = new Thickness(9, 5, 9, 5), VerticalContentAlignment = VerticalAlignment.Center }; actionFields.Children.Add(_stepName); actionHeader.Child = actionFields; Grid.SetRow(actionHeader, 1); root.Children.Add(actionHeader);
            Grid body = new Grid { Margin = new Thickness(20, 14, 20, 12), Background = Brushes.White }; body.RowDefinitions.Add(new RowDefinition { Height = new GridLength(44) }); body.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            DockPanel tools = new DockPanel { LastChildFill = false }; Grid searchHost = new Grid { Width = 340, Height = 34 }; _search = new TextBox { Height = 34, Padding = new Thickness(36, 6, 10, 6), Text = "搜索DBC信号", Foreground = Text(130, 142, 158), HorizontalAlignment = HorizontalAlignment.Stretch }; _search.GotKeyboardFocus += (s, e) => { if (_search.Text == "搜索DBC信号") { _search.Text = string.Empty; _search.Foreground = Text(37, 49, 67); } }; _search.LostKeyboardFocus += (s, e) => { if (string.IsNullOrWhiteSpace(_search.Text)) { _search.Text = "搜索DBC信号"; _search.Foreground = Text(130, 142, 158); } }; _search.TextChanged += (s, e) => _view.Refresh(); searchHost.Children.Add(_search); searchHost.Children.Add(new TextBlock { Text = "\uE721", FontFamily = new FontFamily("Segoe MDL2 Assets"), FontSize = 14, Foreground = Text(104, 117, 136), VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(12, 0, 0, 0), IsHitTestVisible = false }); tools.Children.Add(searchHost); StackPanel filters = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(10, 0, 0, 0) }; _allFilter = FilterButton("全部"); _selectedFilter = FilterButton("已选"); filters.Children.Add(_allFilter); filters.Children.Add(_selectedFilter); _allFilter.IsChecked = true; tools.Children.Add(filters); body.Children.Add(tools);
            _grid = new DataGrid { AutoGenerateColumns = false, CanUserAddRows = false, CanUserDeleteRows = false, RowHeight = 40, ColumnHeaderHeight = 38, GridLinesVisibility = DataGridGridLinesVisibility.Horizontal, BorderBrush = BorderColor(), BorderThickness = new Thickness(1), SelectionMode = DataGridSelectionMode.Extended, SelectionUnit = DataGridSelectionUnit.FullRow, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, RowStyle = TableRowStyle(), Background = Brushes.White };
            Style headerStyle = new Style(typeof(DataGridColumnHeader)); headerStyle.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty, HorizontalAlignment.Center)); headerStyle.Setters.Add(new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center)); headerStyle.Setters.Add(new Setter(Control.FontWeightProperty, FontWeights.SemiBold)); _grid.ColumnHeaderStyle = headerStyle; Style cellStyle = new Style(typeof(DataGridCell)); cellStyle.Setters.Add(new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center)); _grid.CellStyle = cellStyle;
            Style centerCheck = BlueCheckStyle(); centerCheck.Setters.Add(new Setter(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center)); centerCheck.Setters.Add(new Setter(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center)); Style centerText = TextStyle(TextAlignment.Center, new Thickness(6, 0, 6, 0)); Style leftText = TextStyle(TextAlignment.Left, new Thickness(12, 0, 8, 0)); Style editorText = new Style(typeof(TextBox)); editorText.Setters.Add(new Setter(Control.HorizontalContentAlignmentProperty, HorizontalAlignment.Center)); editorText.Setters.Add(new Setter(Control.VerticalContentAlignmentProperty, VerticalAlignment.Center)); editorText.Setters.Add(new Setter(Control.PaddingProperty, new Thickness(6, 0, 6, 0)));
            _grid.Columns.Add(DataGridCheckHelpers.BoundCheckColumn(_readMode ? "读取" : "使用", "Use", 72, centerCheck)); _grid.Columns.Add(new DataGridTextColumn { Header = "信号", Binding = new Binding("Name"), Width = 300, IsReadOnly = true, ElementStyle = leftText }); _grid.Columns.Add(new DataGridTextColumn { Header = _readMode ? "当前值" : "实际值（可编辑）", Binding = new Binding("ValueText") { Mode = BindingMode.TwoWay, UpdateSourceTrigger = UpdateSourceTrigger.PropertyChanged }, Width = 150, IsReadOnly = _readMode, ElementStyle = centerText, EditingElementStyle = editorText }); _grid.Columns.Add(new DataGridTextColumn { Header = "单位", Binding = new Binding("Unit"), Width = 90, IsReadOnly = true, ElementStyle = centerText }); _grid.Columns.Add(new DataGridTextColumn { Header = "原始范围", Binding = new Binding("RawRange"), Width = 165, IsReadOnly = true, ElementStyle = centerText }); _grid.Columns.Add(new DataGridTextColumn { Header = "枚举说明", Binding = new Binding("EnumText"), Width = new DataGridLength(1, DataGridLengthUnitType.Star), IsReadOnly = true, ElementStyle = leftText }); _view = new ListCollectionView(_rows); _view.Filter = FilterRow; _grid.ItemsSource = _view; Grid.SetRow(_grid, 1); body.Children.Add(_grid); Grid.SetRow(body, 1); root.Children.Add(body);
