        private static TextBlock FieldLabel(string text, double left) { return new TextBlock { Text = text, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(left, 0, 8, 0) }; }
        private static TextBox ReadOnlyField(string text, double width) { return new TextBox { Text = text ?? string.Empty, Width = width, Height = 34, IsReadOnly = true, Padding = new Thickness(9, 5, 9, 5), VerticalContentAlignment = VerticalAlignment.Center, Background = new SolidColorBrush(Color.FromRgb(242, 245, 249)), BorderBrush = BorderColor() }; }
        private ToggleButton FilterButton(string text) { ToggleButton button = new ToggleButton { Content = text, MinWidth = 94, Height = 34, Style = SegmentStyle(), Margin = new Thickness(0), Cursor = Cursors.Hand }; button.Click += (s, e) => { _filter = text; if (_allFilter != null) _allFilter.IsChecked = ReferenceEquals(button, _allFilter); if (_selectedFilter != null) _selectedFilter.IsChecked = ReferenceEquals(button, _selectedFilter); _view.Refresh(); }; return button; }
        private bool FilterRow(object value) { DbcSignalEditRow row = value as DbcSignalEditRow; if (row == null) return false; string search = _search.Text == "搜索DBC信号" ? string.Empty : (_search.Text ?? string.Empty).Trim(); return (search.Length == 0 || (row.Name + " " + row.Unit + " " + row.RawRange + " " + row.EnumText).IndexOf(search, StringComparison.OrdinalIgnoreCase) >= 0) && (_filter == "全部" || row.Use); }
        private void RowChanged(object sender, PropertyChangedEventArgs e) { DbcSignalEditRow row = sender as DbcSignalEditRow; if (_readMode && !_guard && e.PropertyName == "Use" && row != null && row.Use) { _guard = true; foreach (DbcSignalEditRow other in _rows.Where(value => value != row && value.Use)) other.Use = false; _guard = false; } RefreshFooter(); if (_filter == "已选") _view.Refresh(); }
        private void SetAll(bool selected) { if (_readMode && selected) { DbcSignalEditRow first = _rows.FirstOrDefault(); if (first != null) first.Use = true; return; } foreach (DbcSignalEditRow row in _rows) row.Use = selected; }
        private void RefreshFooter() { int selected = _rows.Count(value => value.Use); if (_useHeader != null) _useHeader.IsChecked = selected == 0 ? false : selected == _rows.Count ? true : (bool?)null; _footer.Text = "已选 " + selected + " / " + _rows.Count + (_readMode ? "  ·  读取模式仅允许选择一个信号" : ""); }
        private bool CommitConfiguration() { _grid.CommitEdit(DataGridEditingUnit.Cell, true); _grid.CommitEdit(DataGridEditingUnit.Row, true); List<DbcSignalEditRow> selected = _rows.Where(value => value.Use).ToList(); if (selected.Count == 0) { MessageBox.Show(this, "请至少选择一个DBC信号。", "DBC信号配置", MessageBoxButton.OK, MessageBoxImage.Information); return false; } if (_readMode && selected.Count != 1) { MessageBox.Show(this, "读取DBC信号时只能选择一个信号。", "DBC信号配置", MessageBoxButton.OK, MessageBoxImage.Information); return false; } foreach (DbcSignalEditRow edit in _rows) { DbcSignalEditRow original = _sourceRows.FirstOrDefault(value => ReferenceEquals(value.Signal, edit.Signal) || value.Name == edit.Name); if (original != null) original.CopyConfigurationFrom(edit); } return true; }
        private void Apply(object sender, RoutedEventArgs e) { if (CommitConfiguration()) DialogResult = true; }
        private async void Run_Click(object sender, RoutedEventArgs e) { if (_run == null || !CommitConfiguration()) return; try { _footer.Text = "正在运行：" + StepName; string result = await _run(StepName); _footer.Text = "运行结果：" + result; } catch (Exception ex) { _footer.Text = "运行失败：" + ex.Message; MessageBox.Show(this, ex.Message, "立即运行", MessageBoxButton.OK, MessageBoxImage.Error); } }
        private static Button PrimaryButton(string text) { return new Button { Content = text, MinWidth = 116, Height = 34, Padding = new Thickness(16, 5, 16, 5), Margin = new Thickness(8, 0, 0, 0), Background = new SolidColorBrush(Color.FromRgb(24, 112, 224)), Foreground = Brushes.White, BorderBrush = new SolidColorBrush(Color.FromRgb(24, 112, 224)), BorderThickness = new Thickness(1) }; }
        private static Button SecondaryButton(string text) { return new Button { Content = text, MinWidth = 94, Height = 34, Padding = new Thickness(14, 5, 14, 5), Margin = new Thickness(8, 0, 0, 0), Background = Brushes.White, Foreground = Text(52, 67, 88), BorderBrush = BorderColor(), BorderThickness = new Thickness(1) }; }
        private static Style TableRowStyle() { Style style = new Style(typeof(DataGridRow)); style.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.White)); style.Setters.Add(new Setter(Control.BorderBrushProperty, Brushes.Transparent)); style.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(3, 0, 0, 0))); Trigger selected = new Trigger { Property = DataGridRow.IsSelectedProperty, Value = true }; selected.Setters.Add(new Setter(Control.BackgroundProperty, new SolidColorBrush(Color.FromRgb(235, 244, 255)))); selected.Setters.Add(new Setter(Control.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); style.Triggers.Add(selected); return style; }
        private static Style SegmentStyle() { Style style = new Style(typeof(ToggleButton)); style.Setters.Add(new Setter(Control.BackgroundProperty, Brushes.White)); style.Setters.Add(new Setter(Control.ForegroundProperty, Text(52, 67, 88))); style.Setters.Add(new Setter(Control.BorderBrushProperty, BorderColor())); style.Setters.Add(new Setter(Control.BorderThicknessProperty, new Thickness(1))); FrameworkElementFactory border = new FrameworkElementFactory(typeof(System.Windows.Controls.Border)); border.SetBinding(System.Windows.Controls.Border.BackgroundProperty, new Binding("Background") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.SetBinding(System.Windows.Controls.Border.BorderBrushProperty, new Binding("BorderBrush") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.SetBinding(System.Windows.Controls.Border.BorderThicknessProperty, new Binding("BorderThickness") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); FrameworkElementFactory content = new FrameworkElementFactory(typeof(ContentPresenter)); content.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); content.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); content.SetBinding(ContentPresenter.ContentProperty, new Binding("Content") { RelativeSource = new RelativeSource(RelativeSourceMode.TemplatedParent) }); border.AppendChild(content); style.Setters.Add(new Setter(Control.TemplateProperty, new ControlTemplate(typeof(ToggleButton)) { VisualTree = border })); Trigger selected = new Trigger { Property = ToggleButton.IsCheckedProperty, Value = true }; selected.Setters.Add(new Setter(Control.BackgroundProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); selected.Setters.Add(new Setter(Control.ForegroundProperty, Brushes.White)); selected.Setters.Add(new Setter(Control.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)))); style.Triggers.Add(selected); return style; }
        private static Style BlueCheckStyle() { Style style = new Style(typeof(CheckBox)); FrameworkElementFactory root = new FrameworkElementFactory(typeof(System.Windows.Controls.Border)); root.Name = "CheckBoxSquare"; root.SetValue(FrameworkElement.WidthProperty, 16d); root.SetValue(FrameworkElement.HeightProperty, 16d); root.SetValue(System.Windows.Controls.Border.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(139, 151, 168))); root.SetValue(System.Windows.Controls.Border.BorderThicknessProperty, new Thickness(1)); FrameworkElementFactory mark = new FrameworkElementFactory(typeof(TextBlock)); mark.Name = "CheckMark"; mark.SetValue(TextBlock.TextProperty, "✓"); mark.SetValue(TextBlock.ForegroundProperty, Brushes.White); mark.SetValue(TextBlock.FontSizeProperty, 12d); mark.SetValue(TextBlock.FontWeightProperty, FontWeights.Bold); mark.SetValue(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Center); mark.SetValue(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center); mark.SetValue(UIElement.VisibilityProperty, Visibility.Collapsed); root.AppendChild(mark); ControlTemplate template = new ControlTemplate(typeof(CheckBox)) { VisualTree = root }; Trigger on = new Trigger { Property = ToggleButton.IsCheckedProperty, Value = true }; on.Setters.Add(new Setter(System.Windows.Controls.Border.BackgroundProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)), "CheckBoxSquare")); on.Setters.Add(new Setter(System.Windows.Controls.Border.BorderBrushProperty, new SolidColorBrush(Color.FromRgb(24, 112, 224)), "CheckBoxSquare")); on.Setters.Add(new Setter(UIElement.VisibilityProperty, Visibility.Visible, "CheckMark")); template.Triggers.Add(on); style.Setters.Add(new Setter(Control.TemplateProperty, template)); return style; }
        private static Style TextStyle(TextAlignment alignment, Thickness margin) { Style style = new Style(typeof(TextBlock)); style.Setters.Add(new Setter(TextBlock.TextAlignmentProperty, alignment)); style.Setters.Add(new Setter(FrameworkElement.HorizontalAlignmentProperty, HorizontalAlignment.Stretch)); style.Setters.Add(new Setter(FrameworkElement.VerticalAlignmentProperty, VerticalAlignment.Center)); style.Setters.Add(new Setter(FrameworkElement.MarginProperty, margin)); style.Setters.Add(new Setter(TextBlock.TextTrimmingProperty, TextTrimming.CharacterEllipsis)); return style; }
        private static SolidColorBrush Text(byte r, byte g, byte b) { return new SolidColorBrush(Color.FromRgb(r, g, b)); }
        private static SolidColorBrush BorderColor() { return new SolidColorBrush(Color.FromRgb(211, 221, 234)); }
